def transform(grid):
    h, w = len(grid), len(grid[0])

    # A clue is a long, uniform line. Try horizontal, vertical, and both
    # diagonal orientations, selecting the orientation containing the most
    # cells in uniform lines.
    directions = (
        (lambda r, c: r),
        (lambda r, c: c),
        (lambda r, c: c - r),
        (lambda r, c: c + r),
    )

    best = None
    best_score = -1
    for key_fn in directions:
        groups = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    groups.setdefault(key_fn(r, c), []).append(color)

        stripes = {}
        for key, colors in groups.items():
            if len(colors) >= 2 and all(x == colors[0] for x in colors):
                stripes[key] = colors[0]

        score = sum(len(groups[k]) for k in stripes)
        if score > best_score:
            best_score = score
            best = (key_fn, stripes)

    key_fn, stripes = best
    period = len(stripes)
    if period == 0:
        return [row[:] for row in grid]

    # Each clue gives the color for its position in the repeating stripe cycle.
    pattern = {key % period: color for key, color in stripes.items()}
    fallback = next(iter(pattern.values()))
    return [[pattern.get(key_fn(r, c) % period, fallback)
             for c in range(w)] for r in range(h)]
